mapper.select:
SELECT id, teacher_id, class_id, subject_id, created_at
FROM teacher_class
WHERE teacher_id = #{teacherId}

SELECT tc.teacher_id AS teacherId, tc.class_id AS classId, c.class_name AS className, tc.subject_id AS subjectId, s.subject_name AS subjectName, (c.head_teacher_id = tc.teacher_id) AS isHeadTeacher FROM teacher_class tc JOIN class c ON c.id = tc.class_id AND c.deleted = 0 JOIN subject s ON s.id = tc.subject_id AND s.deleted = 0 WHERE tc.teacher_id IN
#{id}
ORDER BY tc.teacher_id, c.class_name, s.subject_name
